import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../route_generator.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/text_styles.dart';
import '../../widgets/desktop/desktop_app_bar.dart';
import '../../widgets/desktop/desktop_scaffold.dart';
import 'settings_menu.dart';
import 'settings_menu/advanced_settings/advanced_settings.dart';
import 'settings_menu/backup_and_restore/backup_and_restore_settings.dart';
import 'settings_menu/currency_settings/currency_settings.dart';
import 'settings_menu/language_settings/language_settings.dart';
import 'settings_menu/nodes_settings.dart';
import 'settings_menu/security_settings.dart';
import 'settings_menu/startup_settings.dart';
import 'settings_menu/syncing_preferences_settings.dart';
import 'settings_menu/tor_settings/tor_settings.dart';

class DesktopSettingsView extends ConsumerStatefulWidget {
  const DesktopSettingsView({super.key});

  static const String routeName = "/desktopSettings";

  @override
  ConsumerState<DesktopSettingsView> createState() =>
      _DesktopSettingsViewState();
}

class _DesktopSettingsViewState extends ConsumerState<DesktopSettingsView> {
  @override
  Widget build(BuildContext context) {
    final page = DesktopSettingsPage
        .values[ref.watch(selectedSettingsMenuItemStateProvider)];
    final (key, route) = switch (page) {
      DesktopSettingsPage.backupRestore => (
        "settingsBackupRestoreDesktopKey",
        BackupRestoreSettings.routeName,
      ),
      DesktopSettingsPage.security => (
        "settingsSecurityDesktopKey",
        SecuritySettings.routeName,
      ),
      DesktopSettingsPage.currency => (
        "settingsCurrencyDesktopKey",
        CurrencySettings.routeName,
      ),
      DesktopSettingsPage.tor => (
        "settingsTorDesktopKey",
        TorSettings.routeName,
      ),
      DesktopSettingsPage.nodes => (
        "settingsNodesDesktopKey",
        NodesSettings.routeName,
      ),
      DesktopSettingsPage.startup => (
        "settingsStartupDesktopKey",
        StartupSettings.routeName,
      ),
      DesktopSettingsPage.appearance => (
        "settingsLanguageDesktopKey",
        LanguageOptionSettings.routeName,
      ),
      DesktopSettingsPage.syncing => (
        "settingsSyncingPreferencesDesktopKey",
        SyncingPreferencesSettings.routeName,
      ),
      DesktopSettingsPage.advanced => (
        "settingsAdvancedDesktopKey",
        AdvancedSettings.routeName,
      ),
    };
    return DesktopScaffold(
      background: Theme.of(context).extension<StackColors>()!.background,
      appBar: const DesktopAppBar(
        isCompactHeight: true,
        leading: Row(
          children: [SizedBox(width: 24, height: 24), DesktopSettingsTitle()],
        ),
      ),
      body: Row(
        children: [
          const Padding(
            padding: EdgeInsets.all(15.0),
            child: Align(
              alignment: Alignment.topLeft,
              child: SingleChildScrollView(child: SettingsMenu()),
            ),
          ),
          Expanded(
            child: Navigator(
              key: Key(key),
              onGenerateRoute: RouteGenerator.generateRoute,
              initialRoute: route,
            ),
          ),
        ],
      ),
    );
  }
}

class DesktopSettingsTitle extends StatelessWidget {
  const DesktopSettingsTitle({super.key});

  @override
  Widget build(BuildContext context) {
    return Text("Settings", style: STextStyles.desktopH3(context));
  }
}
